func (this *Extended) HandleBalance(client ccxt.ClientInterface, message map[string]any) {
	//
	//     {
	//         "type": "BALANCE",
	//         "data": {
	//             "balance": {
	//                 "collateralName": "BTC",
	//                 "balance": "100.000000",
	//                 "equity": "20.000000",
	//                 "availableForTrade": "3.000000",
	//                 "availableForWithdrawal": "4.000000",
	//                 "updatedTime": 1699976104901
	//             },
	//             "spotBalances": [
	//                 {
	//                     "asset": "BTC",
	//                     "balance": "0.5",
	//                     "availableToWithdraw": "0.5",
	//                     "updatedAt": 1701563440
	//                 }
	//             ]
	//         },
	//         "ts": 1715885952304,
	//         "seq": 1
	//     }
	//
	// merge updates into the existing balance object instead of building a
	// fresh one: a consumer awakened by an earlier message holds a reference
	// to this.balance, and ccxt.Client.resolve is a no-op while nobody is
	// awaiting, so a replaced object would make updates landing in that
	// window invisible to the consumer forever (issue #26773)
	if this.Balance == nil {
		this.Balance = map[string]any{}
	}
	var data map[string]any
	data, _ = message["data"].(map[string]any)
	if data == nil {
		data = map[string]any{}
	}
	this.Balance["info"] = data
	var balance, _ = data["balance"].(map[string]any)
	if balance != nil {
		var currencyId *string = this.SafeString(balance, "collateralName")
		var code *string = this.SafeCurrencyCode(currencyId)
		if code != nil {
			var account map[string]any = this.Account()
			account["free"] = this.SafeString(balance, "availableForWithdrawal")
			account["total"] = this.SafeString(balance, "balance")
			this.Balance[*code] = account
		}
	}
	var spotBalances []any = ccxt.SafeListTyped(data, "spotBalances")
	for i := 0; i < len(spotBalances); i++ {
		var spotBalance, _ = spotBalances[i].(map[string]any)
		var currencyId *string = this.SafeString(spotBalance, "asset")
		var code *string = this.SafeCurrencyCode(currencyId)
		if code != nil {
			var account map[string]any = this.Account()
			account["free"] = this.SafeString(spotBalance, "availableToWithdraw")
			account["total"] = this.SafeString(spotBalance, "balance")
			this.Balance[*code] = account
		}
	}
	var timestamp *int64 = this.SafeInteger(message, "ts")
	if timestamp != nil {
		this.Balance["timestamp"] = *timestamp
	} else {
		this.Balance["timestamp"] = nil
	}
	if ptrValue := this.Iso8601(timestamp); ptrValue != nil {
		this.Balance["datetime"] = *ptrValue
	} else {
		this.Balance["datetime"] = nil
	}
	this.Balance, _ = this.SafeBalance(this.Balance).(map[string]any)
	client.Resolve(this.Balance, "balance")
}

